/**
 * Allows the user to supply one or more offsets that are used to search for structures that have
 * any of those offsets.   
 */
public class FindStructuresByOffsetAction : DockingAction {

	public static readonly string NAME = "Find Structures by Offset";

	private DataTypeManagerPlugin plugin;

	public FindStructuresByOffsetAction(DataTypeManagerPlugin plugin, string menuSubGroup) : base(NAME, plugin.getName())
    {
		this.plugin = plugin;

		setMenuBarData(
			new MenuData(new string[] { NAME + "..." }, null, "VeryLast", -1, menuSubGroup));
		setHelpLocation(new HelpLocation("DataTypeManagerPlugin", "Find_Structures_By_Offset"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {

		NumberRangeInputDialog inputDialog = new NumberRangeInputDialog(NAME, "Offset(s)");
		inputDialog.setHelpLocation(getHelpLocation());
		if (!inputDialog.show()) {
			return;
		}

		SortedRangeList values = inputDialog.getValue();
		DataTypesProvider newProvider = plugin.createProvider();
		newProvider.setTitle(NAME);
		DataTypeArchiveGTree tree = newProvider.getGTree();
		tree.setFilterProvider(
			new SecondaryTreeFilterProvider(tree, new OffsetGTreeFilter(values)));
		newProvider.setVisible(true);
	}

	private class OffsetGTreeFilter : GTreeFilter {

		private SortedRangeList offsets;

		OffsetGTreeFilter(SortedRangeList offsets) {
			this.offsets = offsets;
		}

		/* @Override */
		public bool showFilterMatches() {
			return true;
		}

		/* @Override */
		public bool acceptsNode(GTreeNode node) {
			if (!(node is DataTypeNode)) {
				return false;
			}
			DataTypeNode dataTypeNode = (DataTypeNode) node;
			DataType dataType = dataTypeNode.getDataType();
			if (!(dataType is Structure)) {
				return false;
			}

			Structure structure = (Structure) dataType;
			OffsetIterator it = new OffsetIterator(structure);
			foreach (Integer structureOffset in CollectionUtils.asIterable(it)) {
				foreach (Range range in offsets) {
					if (range.contains(structureOffset)) {
						return true;
					}
					if (structureOffset < range.min) {
						// ranges are ascending sorted order; the structure offset is already 
						// smaller than this range, so no more ranges can match
						break;
					}
				}
			}

			return false;
		}

		private class OffsetIterator : Iterator<Integer> {

			private DataTypeComponent[] components;
			private int index = 0;
			private int length;

			OffsetIterator(Structure s) {
				this.components = s.getComponents();
				this.length = components.length;
			}

			/* @Override */
			public bool hasNext() {
				if (index >= length) {
					return false;
				}
				return true;
			}

			/* @Override */
			public Integer next() {
				DataTypeComponent dtc = components[index++];
				return dtc.getOffset();
			}
		}
	}
}
